    def parse_version(version):
        # Split build metadata (after +)
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release (after -)
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert to comparable tuples: (is_digit, numeric_value_or_string)
            prerelease_tuple = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def compare_key(item):
        version, original_index = item
        parsed = parse_version(version)
        major, minor, patch, prerelease_tuple = parsed

        # For sorting: version without prerelease comes after version with prerelease
        # So we use (major, minor, patch, has_no_prerelease, prerelease_tuple, original_index)
        # where has_no_prerelease is True (1) if no prerelease, False (0) if has prerelease
        if prerelease_tuple is None:
            # No pre-release: sorts after same version with pre-release
            return (major, minor, patch, 1, (), original_index)
        else:
            # Has pre-release: sorts before same version without pre-release
            return (major, minor, patch, 0, prerelease_tuple, original_index)

    # Add original indices to maintain order for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort using the comparison key
    sorted_versions = sorted(indexed_versions, key=compare_key)

    # Return just the version strings
    return [v for v, _ in sorted_versions]

